import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const railWidth = 3.6;
  const railHeight = 0.5;
  const railZ = 0.15;
  const entrySpacing = 0.68;

  // Rail background mesh
  const railGeo = new THREE.PlaneGeometry(railWidth, railHeight);
  const railMat = new THREE.MeshStandardNodeMaterial({
    color: 0x14141a,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
  });
  const railMesh = new THREE.Mesh(railGeo, railMat);
  railMesh.position.z = railZ;
  group.add(railMesh);

  // Navigation entries
  const navItems = [
    { label: 'HOME', index: 0, active: true },
    { label: 'FEATURES', index: 1, active: false },
    { label: 'COLLECTION', index: 2, active: false },
    { label: 'PRICING', index: 3, active: false },
    { label: 'JOURNAL', index: 4, active: false },
  ];

  let activeIndex = 0;
  const entryGroups = [];

  navItems.forEach(({ label, index, active }) => {
    const xStart = -entrySpacing * 2;
    const xPos = xStart + index * entrySpacing;

    // Render text via MSDF
    const textMesh = ctx.fontAtlas.createText(label, {
      fontSize: 13,
      fontWeight: active ? 700 : 400,
      letterSpacing: 0.08,
      color: active ? 0xe8ecf2 : 0xa6adba,
    });

    const entryGroup = new THREE.Group();
    entryGroup.add(textMesh);
    entryGroup.position.set(xPos, 0, railZ + 0.01);
    entryGroup.userData = { index, label, active };

    group.add(entryGroup);
    entryGroups.push(entryGroup);
  });

  // Active underline bar
  const underlineGeo = new THREE.PlaneGeometry(0.28, 0.025);
  const underlineMat = new THREE.MeshBasicNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
  });
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  const xStart = -entrySpacing * 2;
  underline.position.set(xStart, -0.15, railZ + 0.02);
  group.add(underline);

  // Contact shadow
  const shadowGeo = new THREE.PlaneGeometry(railWidth + 0.2, 0.05);
  const shadowMat = new THREE.MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.06, railZ - 0.01);
  group.add(shadow);

  // Event handlers
  group.userData.handlers = {
    onNavigate: (index) => {
      if (index === activeIndex) return;
      activeIndex = index;

      // Update text colors
      entryGroups.forEach((eg, i) => {
        const textMesh = eg.children[0];
        if (textMesh && textMesh.material && textMesh.material.color) {
          textMesh.material.color.setHex(i === index ? 0xe8ecf2 : 0xa6adba);
        }
      });

      // Animate underline to new position
      const newX = xStart + index * entrySpacing;
      gsap.to(underline.position, {
        x: newX,
        duration: 0.26,
        ease: 'power2.inOut',
        overwrite: 'auto',
      });
    },
  };

  // Mount animation (rise-in)
  group.position.y = 0.4;
  gsap.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf([group.position, underline.position, ...entryGroups]);

    railGeo.dispose();
    railMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return group;
}
